#!/nix/store/3n4qphl9s728sz8frmpqqrv9b1m87g68-python3-3.14.7/bin/python

import time

from queue_common import connect


def process_one():
    connection = connect()
    try:
        connection.execute("BEGIN IMMEDIATE")
        row = connection.execute(
            "SELECT id, payload FROM jobs "
            "WHERE status = 'queued' AND attempts = 0 "
            "ORDER BY rowid LIMIT 1"
        ).fetchone()
        if row is None:
            connection.rollback()
            return False

        job_id, payload = row
        changed = connection.execute(
            "UPDATE jobs SET status = 'completed', result = ?, attempts = 1 "
            "WHERE id = ? AND status = 'queued' AND attempts = 0",
            ("processed:" + payload, job_id),
        ).rowcount
        if changed != 1:
            connection.rollback()
            return False
        connection.commit()
        return True
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()


if __name__ == "__main__":
    while True:
        try:
            if not process_one():
                time.sleep(0.1)
        except Exception:
            time.sleep(1.0)

